class gsl_vector(ctypes.Structure):
    _fields_ = [
        ("size", ctypes.c_int),
        ("stride", ctypes.c_int),
        ("block", ctypes.POINTER(ctypes.c_double)),
        ("owner", ctypes.c_int),
    ]

    def __init__(self, size):
        self.size = size
        self.stride = 1
        self.block = (ctypes.c_double * size)()
        self.owner = 1

    def get_data(self):
        return np.ctypeslib.as_array(self.block, shape=(self.size,))

    @classmethod
    def from_numpy(cls, arr):
        if not isinstance(arr, np.ndarray) or arr.dtype != np.float64:
            raise ValueError("Input must be a numpy array of type float64.")
        vec = cls(arr.shape[0])
        for i in range(arr.shape[0]):
            vec.block[i] = arr[i]
        return vec

