        result = gsl.gsl_ringbuf_push(ringbuf.ptr, ctypes.c_double(value))
        if result != 0:
            raise RuntimeError(f"Failed to insert value: {value}")

def copy_ringbuf_to_list(ringbuf):
    size = ctypes.sizeof(ringbuf.ptr.contents) - ctypes.sizeof(ctypes.c_int * 2)
    data_type = ctypes.c_double * (size // ctypes.sizeof(ctypes.c_double))
    data = ctypes.cast(ringbuf.ptr.contents, ctypes.POINTER(data_type)).contents
    read_pos = ctypes.c_int.from_address(ctypes.addressof(ringbuf.ptr.contents) + size)
    write_pos = ctypes.c_int.from_address(ctypes.addressof(ringbuf.ptr.contents) + size + ctypes.sizeof(ctypes.c_int))

    result = []
    for i in range(size // ctypes.sizeof(ctypes.c_double)):
        index = (read_pos.value + i) % len(data)
        result.append(data[index])
    return result

