class GSLMatrix:

    def __init__(self, matrix):
        self.matrix = np.array(matrix, dtype=ctypes.c_double)
        self.nrows = self.matrix.shape[0]
        self.ncols = self.matrix.shape[1]
        assert self.nrows == self.ncols, "Matrix must be square"
        # Load necessary libraries
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        self.gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        # Define function signature for gsl_linalg_cholesky_decomp
        self.gsl.gsl_linalg_cholesky_decomp.argtypes = [
            ctypes.POINTER(ctypes.POINTER(ctypes.c_double)),
            ctypes.c_int
        ]
        self.gsl.gsl_linalg_cholesky_decomp.restype = ctypes.c_int

    def is_positive_definite(self, matrix):
        try:
            return np.all(np.linalg.eigvals(matrix) > 0)
        except np.linalg.LinAlgError:
            return False

    def cholesky_decomp(self, matrix):
        if not self.is_positive_definite(matrix):
            raise ValueError("Matrix must be positive definite.")

        n = self.nrows
        mat = (ctypes.POINTER(ctypes.c_double) * n)()
        for i in range(n):
            mat[i] = matrix[i].ctypes.data_as(ctypes.POINTER(ctypes.c_double))

        result_code = self.gsl.gsl_linalg_cholesky_decomp(mat, n)
        if result_code != 0:
            raise RuntimeError(f"GSL error during Cholesky decomposition: {result_code}")

        # Extract lower triangular part from the modified matrix
        lower_triangular = [[mat[i][j] if i >= j else 0.0 for j in range(n)] for i in range(n)]
        return lower_triangular

