def cblas_zdscal(N, alpha, X, incX):
    if not isinstance(N, int) or N <= 0:
        raise ValueError("N must be a positive integer.")
    if not isinstance(alpha, (int, float)):
        raise ValueError("alpha must be a real number.")
    if not isinstance(X, list) or any(not isinstance(x, complex) for x in X):
        raise ValueError("X must be a list of complex numbers.")
    if len(X) < 1:
        raise ValueError("X cannot be empty.")
    if not isinstance(incX, int) or incX <= 0:
        raise ValueError("incX must be a positive integer.")

    # Convert X to a ctypes array of double complex (8 bytes per float => 16 bytes per complex)
    X_array = (ctypes.c_double * (len(X) * 2))()
    for i in range(len(X)):
        X_array[i * 2] = X[i].real
        X_array[i * 2 + 1] = X[i].imag

    # Define function prototype
    cblas_zdscal_func = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so").cblas_zdscal
    cblas_zdscal_func.argtypes = [
        ctypes.c_int,
        ctypes.c_double,
        ctypes.POINTER(ctypes.c_double),
        ctypes.c_int
    ]

    cblas_zdscal_func.restype = None

    # Call the function
    cblas_zdscal_func(N, alpha, X_array, incX)

    # Convert result back to Python complex list
    Y = [complex(X_array[i * 2], X_array[i * 2 + 1]) for i in range(N)]
    return Y

